if(document.querySelector('.portal-body')){
 const collectionModal=showModal;showModal=function(html){collectionModal(html);$('#modal').dataset.collectionOrder=''};
 const collectionReceiver=window.WK.receiveOrders;window.WK.receiveOrders=function(list){collectionReceiver(list);const active=$('#modal').dataset.collectionOrder,o=list.find(o=>o.id===active);if($('#modal').open&&active&&o&&!WCPayment.canPay(o)){$('#modal').close();notify('Payment status changed. Review the order before collecting.')}};
 const cashSummary=window.WCAdminPayment;
 window.WCAdminPayment=o=>cashSummary(o)+(o.paymentMethod==='UPI'?'':`<section class="payment-summary cash-collect"><b>${escape(o.paymentMethod)} · ${escape(paymentLabel(o))}</b>${!['New','Pending confirmation','Rejected'].includes(o.status)&&o.paymentStatus==='Unpaid'?`<button class="portal-button" data-collect-order="${escape(o.id)}">Collect ${money(o.total)} · cash or UPI</button>`:''}${o.paymentStatus==='Refund required'?`<button class="portal-button" data-cash-refund="${escape(o.id)}">Record cash refund · ${money(o.total)}</button>`:''}</section>`)+(o.paymentMethod==='UPI'&&WCPayment.canPay(o)?`<button class="portal-button" data-order-qr="${escape(o.id)}">Show order QR · ${money(o.total)}</button>`:'');
 function cashCollect(id,refund=false){const o=orders.find(o=>o.id===id);if(!o||!allowed())return;showModal(`<h2>${refund?'Record cash returned':'Collect this order'}</h2><p>${escape(o.name)}</p><div class="upi-amount">${money(o.total)}</div><p class="form-note">The total includes all items and ${o.fulfillment==='pickup'?'free pickup':'the delivery fee'}. ${refund?'Return the money first, then record it here.':'Choose cash received or show the customer an amount-filled UPI QR.'}</p>${!refund?'<button class="primary wide" id="collectasupi">Generate UPI QR for this total</button>':''}<form id="recordcash"><label>Amount ${refund?'returned':'received'} (₹)<input name="amount" type="number" required min=".01" step=".01" value="${o.total}"></label><label class="consent"><input type="checkbox" required> ${refund?'I returned the full cash amount to the customer.':'I have received and counted the full cash amount.'}</label><button class="primary wide">${refund?'Record completed cash refund':'Mark cash received'}</button></form>`);if($('#collectasupi'))$('#collectasupi').onclick=async e=>{e.target.disabled=true;try{const result=await window.WKCloud.collectOrderPayment({id,action:'upi'});if(!allowed())return;showModal(qrPanel(result.total,result.paymentRef,'Collect this order.')+`<p class="form-note">This order now uses UPI. Check the bank receipt before recording payment.</p><button class="portal-button" id="checkcollected">Check bank & confirm receipt</button>`);$('#modal').dataset.collectionOrder=id;$('#checkcollected').onclick=()=>bankReview(id,'confirm')}catch(err){notify(err.message);e.target.disabled=false}};$('#recordcash').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await window.WKCloud.collectOrderPayment({id,action:refund?'cash-refund':'cash',amount:Number(new FormData(e.target).get('amount')),checkedCash:true});$('#modal').close();notify(refund?'Cash refund recorded':'Cash received and recorded')}catch(err){notify(err.message);button.disabled=false}}}
 document.addEventListener('click',event=>{const cash=event.target.closest('[data-collect-order]'),qr=event.target.closest('[data-order-qr]'),refund=event.target.closest('[data-cash-refund]');if(cash)cashCollect(cash.dataset.collectOrder);if(refund)cashCollect(refund.dataset.cashRefund,true);if(qr&&allowed()){const o=orders.find(o=>o.id===qr.dataset.orderQr);if(o&&WCPayment.canPay(o)){showModal(qrPanel(o.total,o.paymentRef,'Collect this order.')+'<p class="form-note">Check the bank statement before marking paid in this order.</p>');$('#modal').dataset.collectionOrder=o.id}}});
}
